<?php
declare(strict_types=1);
require dirname(__DIR__).'/api/agent-admin-brain.php';
require dirname(__DIR__).'/api/agent-integration-coverage.php';
$coverage=sf_agent_integration_coverage(sf_admin_agent_module_routes());
$failed=0;
$assert=static function(bool $ok,string $label)use(&$failed):void{
    echo ($ok?'PASS ':'FAIL ').$label.PHP_EOL;
    if(!$ok)$failed++;
};
$tools=$coverage['tools'];
$index=[];
foreach($tools as $row)$index[$row['id']]=$row;
$assert($coverage['schema']==='stonefellow.agent-integration-coverage.v1' && $coverage['scope']==='stonefellow_only','Explicit Stonefellow-only diagnostic contract');
$assert($coverage['checks_passed'] && $coverage['registry_passed'],'Existing registry contracts and coverage pass');
$assert($coverage['registered_tools']===count(sf_agent_tool_registry()) && $coverage['registered_skills']===count(sf_agent_skill_definitions()),'Complete live tool and skill counts');
$assert(!$coverage['missing_skill_bindings'] && !$coverage['invalid_skill_bindings'],'Every exposed tool has a valid skill');
$assert($coverage['admin_navigation_only_count']===count(sf_admin_agent_module_routes()) && $coverage['admin_navigation_only_count']===23,'All 23 module routes inventoried');
$assert(!$coverage['invalid_module_contracts'],'All module routes resolve to bounded navigation');
$assert(count(array_filter($coverage['admin_module_routes'],static fn($row)=>$row['conversation_integration']!=='navigation_only' || $row['record_read_verified'] || $row['record_write_verified']))===0,'Navigation is never reported as CRUD');
$assert(count($coverage['reviewed_action_eligible'])===7,'Seven explicitly allowlisted reviewed executors, no unapproved writes');
$assert($index['catalog_metadata_update']['classification']==='reviewed_action_eligible' && $index['catalog_metadata_update']['requires_confirmation'],'Catalog metadata remains exact-review write');
$assert($index['campaign_send_email']['classification']==='owner_workflow_only' && !$index['campaign_send_email']['may_prepare_reviewed_proposal'],'Campaign sending stays owner-controlled');
$assert($index['agent_song_catalog_publish']['classification']==='owner_workflow_only' && !$index['agent_song_catalog_publish']['may_prepare_reviewed_proposal'],'Song publication is not promoted to generic executor');
$assert($index['agent_brain_log']['classification']==='internal_only' && !$index['agent_brain_log']['skill_ids'],'Internal audit never exposed as skill');
$assert($index['admin_module_navigate']['classification']==='browser_action' && !$index['admin_module_navigate']['may_prepare_reviewed_proposal'],'Navigation is browser-only');
$assert(count(array_filter($tools,static fn($row)=>$row['direct_agent_execution']))===0,'No registry entry claims direct execution');
$assert(!sf_agent_tool_allowed('crm_aggregate','fan',true) && !sf_agent_tool_allowed('catalog_metadata_update','fan',true),'Customer roles remain isolated from Admin tools');
$bad=sf_admin_agent_module_routes();$bad['invented_admin_write']=['view'=>'catalog','label'=>'Write','pattern'=>'/.*/','reply'=>'Write'];
$injected=sf_agent_integration_coverage($bad);
$assert(!$injected['checks_passed'] && in_array('invented_admin_write',$injected['invalid_module_contracts'],true),'Unknown Admin intent fails coverage audit');
$endpoint=(string)file_get_contents(dirname(__DIR__).'/admin/api/agent-tools.php');
$authPos=strpos($endpoint,'sf_admin_require_auth(false)');
$auditPos=strpos($endpoint,"(\$_GET['audit']??'')==='1'");
$assert($authPos!==false && $auditPos!==false && $authPos<$auditPos,'Coverage endpoint authenticates before diagnostics');
$assert(str_contains($endpoint,'sf_agent_integration_coverage(sf_admin_agent_module_routes())'),'Admin-only opt-in endpoint uses live module routes');
$assert(!str_contains($endpoint,'sf_agent_action_execute') && !str_contains($endpoint,'sf_agent_action_prepare'),'Read-only coverage endpoint cannot perform an action');
echo 'Section 91B1: '.(19-$failed).'/19 checks'.PHP_EOL;
exit($failed?1:0);
